  "check_code": "import sqlite3
import re
from pathlib import Path

TARGET_RECEIPTS = {"RCV-2024-09016", "RCV-2025-00019"}
TARGET_POS = {"PO-2024-12044", "PO-2024-12117"}
TARGET_RECEIPT_RULES = {
    "RCV-2024-09016": {"po_id": "PO-2024-12044", "status_terms": ("canceled",), "amount": "90,000"},
    "RCV-2025-00019": {"po_id": "PO-2024-12117", "status_terms": ("administrative close", "administratively closed", "admin_closed"), "amount": "73,000"},
}
TARGET_DISPOSITION_RULES = {
    "PO-2024-12044": {"receipt_id": "RCV-2024-09016", "status_terms": ("canceled",)},
    "PO-2024-12117": {"receipt_id": "RCV-2025-00019", "status_terms": ("administrative close", "administratively closed", "admin_closed")},
}


def _db(ws):
    return Path(ws).resolve().parent / "system" / "peoplesoft_purchasing" / "state.db"


def _result(ok, detail):
    return {"score": 1 if ok else 0, "detail": detail}


def _norm(value):
    return re.sub(r"\s+", " ", str(value or "").strip().lower().replace("_", " "))


def _has_status(text, terms):
    return any(term in text for term in terms)


def _has_close_rationale(text):
    # Require accepted activity plus an explicit exception/close and accounting route.
    return ("accept" in text and ("exception" in text or "close review" in text)
            and any(term in text for term in ("accrual", "liability", "encumbrance", "procurement")))


def check_receipt_exception_flags(ws):
    with sqlite3.connect(_db(ws)) as con:
        con.row_factory = sqlite3.Row
        rows = con.execute(
            "SELECT receipt_id, po_id, exception_flag, exception_reason FROM receipts WHERE receipt_id IN (?, ?)",
            tuple(sorted(TARGET_RECEIPTS)),
        ).fetchall()
    actual = {r["receipt_id"]: dict(r) for r in rows}
    ok = len(actual) == 2
    for receipt_id, rule in TARGET_RECEIPT_RULES.items():
        row = actual.get(receipt_id, {})
        reason = _norm(row.get("exception_reason"))
        ok = ok and row.get("po_id") == rule["po_id"]
        ok = ok and row.get("exception_flag") == 1
        ok = ok and _has_status(reason, tuple(_norm(t) for t in rule["status_terms"]))
        ok = ok and _has_close_rationale(reason)
    return _result(ok, f"receipt rows={actual}")


def check_latest_final_exception_dispositions(ws):
    with sqlite3.connect(_db(ws)) as con:
        con.row_factory = sqlite3.Row
        rows = con.execute(
            """SELECT d.* FROM commitment_dispositions d
               JOIN (SELECT po_id, MAX(decision_version) AS version
                     FROM commitment_dispositions
                     WHERE po_id IN (?, ?) AND review_stage='FINAL'
                     GROUP BY po_id) latest
                 ON latest.po_id=d.po_id AND latest.version=d.decision_version
               WHERE d.review_stage='FINAL' AND d.po_id IN (?, ?)""",
            ("PO-2024-12044", "PO-2024-12117", "PO-2024-12044", "PO-2024-12117"),
        ).fetchall()
    actual = {r["po_id"]: dict(r) for r in rows}
    ok = len(actual) == 2
    ids = []
    for po_id, rule in TARGET_DISPOSITION_RULES.items():
        row = actual.get(po_id, {})
        disposition_id = str(row.get("disposition_id") or "")
        reason = _norm(row.get("reason_text"))
        ids.append(disposition_id)
        ok = ok and re.fullmatch(r"DSP-2025-\d{5}", disposition_id) is not None
        ok = ok and row.get("reviewer_id") == "BUD-0638"
        ok = ok and row.get("review_stage") == "FINAL"
        ok = ok and row.get("disposition_code") == "EXCEPTION"
        ok = ok and row.get("retained_amount_cents") == 0
        ok = ok and row.get("decision_date") == "2025-09-12"
        ok = ok and row.get("decision_version") == 2
        ok = ok and rule["receipt_id"].lower() in reason
        ok = ok and _has_status(reason, tuple(_norm(t) for t in rule["status_terms"]))
        ok = ok and _has_close_rationale(reason)
    ok = ok and len(set(ids)) == 2
    return _result(ok, f"latest final rows={actual}")


def check_unrelated_records_unchanged(ws):
    with sqlite3.connect(_db(ws)) as con:
        con.row_factory = sqlite3.Row
        changed_receipts = con.execute(
            "SELECT receipt_id FROM receipts WHERE exception_flag <> 0 AND receipt_id NOT IN (?, ?)",
            tuple(sorted(TARGET_RECEIPTS)),
        ).fetchall()
        changed_dispositions = con.execute(
            "SELECT disposition_id, po_id FROM commitment_dispositions WHERE po_id NOT IN (?, ?)",
            tuple(sorted(TARGET_POS)),
        ).fetchall()
        purchase_orders = con.execute("SELECT COUNT(*) FROM purchase_orders").fetchone()[0]
    # The pinned baseline has no non-target receipt exception flags and 199 non-target dispositions.
    ok = not changed_receipts and len(changed_dispositions) == 199 and purchase_orders == 186
    return _result(ok, f"non-target flagged receipts={changed_receipts}; non-target dispositions={len(changed_dispositions)}; purchase_orders={purchase_orders}")
